import{_ as i,a0 as u,w as s,s as a,ao as l,I as n,x as e,a1 as o,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"戴文的Linux內核專題：22 配置內核 (18) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：22 配置內核 (18) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：22 配置內核 (18) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：22 配置內核 (18) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/22 The Linux Kernel--Configuring the Kernel Part 18","title":"戴文的Linux內核專題：22 配置內核 (18)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/22 The Linux Kernel--Configuring the Kernel Part 18.md","filePath":"[post].md"}'),d={name:"The Linux Kernel/22 The Linux Kernel--Configuring the Kernel Part 18.md"};function q(I,t,x,m,C,M){const r=u("Link");return s(),a("div",null,[t[11]||(t[11]=l('<h1 id="戴文的linux內核專題-22-配置內核-18" tabindex="-1">戴文的Linux內核專題：22 配置內核 (18) <a class="header-anchor" href="#戴文的linux內核專題-22-配置內核-18" aria-label="Permalink to “戴文的Linux內核專題：22 配置內核 (18)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.616/" alt=""></p><p>你好！準備好閲讀下一篇文章了麼？在本篇中，我們將會討論輔助顯示。輔助顯示是一些小的LCD屏幕；大多數小於或等於128x64。接着，我們會討論用户空間IO驅動，一些虛擬驅動，Hyper-V，開發中驅動，IOMMU，和其他一些內核特性。</p><p>第一個配置輔助顯示的驅動是&quot;KS0108 LCD Controller&quot;。KS0108 LCD Controller是由三星製造的圖形控制器。</p><p>下面可以設置LCD並口地址(Parallel port where the LCD is connected)。第一個並口地址是0x378，下一個是0x278，第三個是0x3BC。這些不是地址唯一的選擇。大多數人不需要改變這個。shell命令&quot;cat /proc/ioports&quot;會列出可用的並口和地址。</p><p>內核可以設置KS0108 LCD 控制器的寫入延時到並口(Delay between each control writing (microseconds))。默認的值大部分是正確的，因此一般不需要更改。</p><p>&quot;CFAG12864B LCD&quot;屏幕是一塊128x64，雙色LCD屏幕。這塊屏幕依賴於KS0108 LCD控制器。</p><p>可以改變這些LCD屏幕的刷新率(Refresh rate (hertz))。通常上，更高的刷新率會導致更多的CPU活動。這意味着一個緩慢的系統需要一個更低的刷新率。</p><p>設置完輔助顯示後，接着設置&quot;Userspace I/O drivers&quot;。用户空間系統允許用户的應用和進程訪問內核中斷和內存地址。啓用了它，一些驅動可以放在用户空間。</p><p>&quot;generic Hilscher CIF Card driver&quot;用於Profibus卡和Hilscher CIF卡。</p><p>&quot;Userspace I/O platform driver&quot;在用户空間創建通用驅動系統。</p><p>下一個驅動和上面的相同，但是增加IRQ處理(Userspace I/O platform driver with generic IRQ handling)。</p><p>下面的驅動又像前面的一個，但是增加了動態內存支持(Userspace platform driver with generic irq and dynamic memory)。</p><p>下面，是一些供應商/設備特性的驅動。</p><p>接着是一些通用PCI/PCIe卡驅動(Generic driver for PCI 2.3 and PCI Express cards)。</p><p>下面的驅動用於&quot;VFIO support for PCI devices&quot;。VFIO代表Virtual Function Input/Output(虛擬功能輸入/輸出)。VFIO允許設備直接以安全方式訪問用户空間。</p><p>&quot;VFIO PCI support for VGA devices&quot;允許VGA通過VFIO被PCI支持。</p><p>接下來是virtio驅動。virtio是一個IO虛擬化平台。這個虛擬軟件用於操作系統虛擬化。這在Linux系統上的虛擬機上運行一個操作系統時需要。</p><p>我們第一個可以配置的virtio驅動是&quot;PCI driver for virtio devices&quot;。這允許虛擬訪問PCI</p><p>&quot;Virtio balloon driver&quot;允許虛擬系統的內存根據需要擴展或減少。通常上，沒有人希望在需要內存的時候，虛擬系統保留它可能不會使用的內存。</p><p>下面的驅動允許內存映射到virtio設備(Platform bus driver for memory mapped virtio devices)。</p><p>如果Linux內核需要運行在微軟的Hyper-V系統上，那麼啓用這個驅動(Microsoft Hyper-V client drivers)。這允許Linux能夠成為Hyper的訪客/客户端系統。</p><p><img src="http://www.linux.org/attachments/kernel_18-png.617/" alt=""></p><p>下面，我們會配置處於開發階段的驅動。這些驅動正在開發當中，可能會變化很快，或者還沒到Linux內核的質量標準。這個分類中的驅動只有Android驅動(在內核3.9.4中)。是的，Andorid使用Linux內核，這使得Andorid變成了一個Linux系統。然而，這仍然有爭議。如果內核是用於Android，那麼最好啓用所有的驅動。</p><p>&quot;Android Binder IPC Driver&quot;提供了對於Binder的支持，它允許Andorid系統進程間相互通信。</p><p>下面可以啓用ashmen驅動(Enable the Anonymous Shared Memory Subsystem)。Ashmem代表&quot;Anonymous SHared MEMory&quot;(虛擬內存共享)或者&quot;Android SHared MEMory&quot;(Andorid共享內存)。</p><p>&quot;Android log driver&quot;提供了完整的Andorid日誌系統。</p><p>&quot;Timed output class driver&quot; 和 &quot;Android timed gpio driver&quot;允許Andorid系統操作GIP引腳並在超時後取消操作。</p><p>&quot;Android Low Memory Killer&quot;會在需要更多內存關閉進程。這個特性會殺死不再使用或活躍的任務。</p><p>&quot;Android alarm driver&quot;使內核在設定的間隔後喚醒。</p><p>在配置完開發階段的驅動後，下面的驅動用於X86平台。這些驅動是 X86 (32-bit)的供應商/設備特定硬件。</p><p>下一個驅動是&quot;Mailbox Hardware Support&quot;。這個框架控制郵箱隊列和硬件郵箱系統的中斷信號。</p><p>&quot;IOMMU Hardware Support&quot;鏈接內存到能夠使用DMA的設備上。IOMMU增強了DMA。IOMMU映射地址並阻止故障設備訪問內存。IOMMU同樣允許硬件訪問比沒有IOMMU更多內存。</p><p>&quot;AMD IOMMU support&quot;提供了對AMD設備更好的IOMMU支持。</p><p>對於AMD IOMMU支持存在調試特性(Export AMD IOMMU statistics to debugfs)。</p><p>存在一個對於AMD硬件的更新版本的IOMMU驅動(AMD IOMMU Version 2 driver)。</p><p>Linux內核同樣支持對Intel設備的IOMMU驅動支持(Support for Intel IOMMU using DMA Remapping Devices)。</p><p>一些設備可能會接受不同的電壓和時鐘頻率。這個驅動允許操作系統控制設備的電壓輸出和時鐘頻率(Generic Dynamic Voltage and Frequency Scaling (DVFS) support)。啓用了這個驅動，可以啓用下面的那些對於電源/性能管理特性。</p><p>&quot;Simple Ondemand&quot;就像上面的，但是隻會基於設備活動改變時鐘頻率。通常上，更多的活動意味着設備需要更快的時鐘速率來使用更多的資源需求。</p><p>&quot;Performance&quot;允許系統設置最高支持的時鐘速度以滿足最好的性能。這會增加電源消耗。</p><p>&quot;Powersave&quot;會設置時鐘頻率到最低以節約電源。</p><p>&quot;Userspace&quot;允許用户空間設置時鐘頻率。</p><p>&quot;External Connector Class (extcon) support&quot;使得用户空間可以監視外部連接器如USB和AC口。這允許應用瞭解是否插入了線纜。用户幾乎都希望啓用這個。如果任何人由於某個合理的理由禁用了它，請告訴我們為什麼這麼做。</p><p>&quot;GPIO extcon support&quot;驅動就像上面的驅動，但是它只對於GPIO管腳。</p><p>接下來是不同的供貨商/設備特定的內存控制器(Memory Controller drivers)。內存芯片控制器可能是獨立的設備或者內置在內存芯片上。這些控制器管理這輸入和輸出的數據流。</p><p>&quot;Industrial I/O support&quot;驅動提供了標準的傳感器接口而不管總線的類型(像PCIe、spi、GPIO等等)。IIO是&quot;Industrial I/O support&quot;(工業IO)的通用縮寫。</p><p>Linux內核提供了大量不同的加速器、放大器模數轉換器、慣性測量單元、光敏傳感器、磁場傳感器和其他許多傳感器和轉換器的支持。</p><p>&quot;Intel Non-Transparent Bridge support&quot;驅動支持連接到系統的PCIe硬件橋。所有到映射內存的寫入會鏡像到兩個系統中。</p><p>&quot;VME bridge support&quot;和上面的相同除了橋使用的是VME，這是一個不同的總線標準。</p><p>&quot;Pulse-Width Modulation (PWM) Support&quot;通過調節從這些設備收到的平均功率調節背光燈和風扇速度。</p><p>&quot;IndustryPack bus support&quot;提供了對IndustryPack總線標準的支持。</p><p>下一篇文章，我們會繼續配置固件驅動。謝謝!</p><hr>',53)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),o(r,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-18.4896/"},{default:p(()=>[...t[0]||(t[0]=[e("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-18.4896/",-1)])]),_:1})]),n("p",null,[t[4]||(t[4]=e("譯者：",-1)),o(r,{href:"https://github.com/geekpi"},{default:p(()=>[...t[2]||(t[2]=[e("geekpi",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),o(r,{href:"https://github.com/wxy"},{default:p(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),o(r,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const f=i(d,[["render",q]]);export{h as __pageData,f as default};
